    private static bool TryGetDescriptorFromGeneratedTable(ulong descriptorLookupKey, out ulong descriptor)
    {
        var low = 0;
        var high = _descriptorLookupTable.Length - 1;
        while (low <= high)
        {
            var mid = low + ((high - low) >> 1);
            var entry = _descriptorLookupTable[mid];
            if (entry.LookupKey == descriptorLookupKey)
            {
                descriptor = entry.Descriptor;
                return descriptor != 0;
            }

            if (entry.LookupKey < descriptorLookupKey)
            {
                low = mid + 1;
            }
            else
            {
                high = mid - 1;
            }
        }

        descriptor = 0;
        return false;
    }
